/* From Uiverse.io by kamehame-ha - Tags: simple, card, scroll snap, clean */
.__UIV_SCOPE__ .red {
  background-color: #f43f5e;
}

.__UIV_SCOPE__ .blue {
  background-color: #3b82f6;
}

.__UIV_SCOPE__ .green {
  background-color: #22c55e;
}

.__UIV_SCOPE__ .scroll-snap-card {
  height: 150px;
  width: 250px;
  scroll-snap-type: y mandatory;
  overflow: auto;
  border-radius: 10px;
}

.__UIV_SCOPE__ .scroll-snap-card .slide {
  width: 100%;
  height: 100%;
  scroll-snap-align: start;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .scroll-snap-card .slide p {
  font-size: 1em;
  color: white;
  font-weight: 700;
}
